sys_data_source.data_loader:
(function loadData(import_set_table, data_source, import_log, last_success_import_time) {

    try {


        inputs = {};
        inputs['attachment_name'] = "test";

        var flowAction = sn_fd.FlowAPI.getRunner()
            .action('x_cesy_service_gr.copy_of_get_ceburu_devices')
            .inForeground()
            .withInputs(inputs)
            .run();


        // 3. Extract the outputs from the completed execution
        var outputs = flowAction.getOutputs();
        var attachmentSysId = outputs['response_body'];

        if (attachmentSysId && attachmentSysId.length == 32) {
            // gs.info('Ceburu Flow Success. Attachment found with ID: ' + attachmentSysId);

            // 4. Initialize the attachment API to extract the raw text content stream
            var attachmentAPI = new GlideSysAttachment();
            var contentStream = attachmentAPI.getContentStream(attachmentSysId);

            // Read the binary data stream lines into a standard string variable
            var reader = new GlideTextReader(contentStream);
            var rawJsonText = "";
            var line = "";

            while ((line = reader.readLine()) != null) {
                rawJsonText += line;
            }

            if (!rawJsonText) {
                gs.error('Ceburu Staging Error: Extracted attachment text file content is empty.');
            }

            // 5. Parse the raw text data into an actionable JSON object
            var responseBody = JSON.parse(rawJsonText);
        }
        var results = responseBody.results;


        for (var i = 0; i < results.length; i++) {

            var item = results[i];

            var spec = item.specifications && item.specifications.length > 0 ? item.specifications[0] : {};

            // =========================
            // DEVICE IMPORT RECORD
            // =========================

            var importRecord = {};
            importRecord.type = "device";
            importRecord.device_id = item.device.id;
			importRecord.correlation_id = item.device.id + '';

            importRecord.hostname = spec.hostname || '';
            importRecord.ip_address = spec.ipaddress || '';
            importRecord.model = spec.model || '';
            importRecord.serial_number = spec.serialno || '';

            importRecord.cpu = spec.cpu || 0;
            importRecord.memory = spec.memory || 0;

            importRecord.health = spec.health || false;

            import_set_table.insert(importRecord);

            // =========================
            // INTERFACE IMPORT RECORD
            // =========================

            var interfaces = item.interfaces && item.interfaces.length > 0 ? item.interfaces : [];
            for (var j = 0; j < interfaces.length; j++) {

                var iface = interfaces[j];

                importRecord = {};

                importRecord.type = "interface";

                // =========================
                // RELATIONSHIP TO PARENT DEVICE
                // =========================

                importRecord.device_id = item.device.id;

                // =========================
                // RECONCILIATION FIELDS
                // =========================

                importRecord.interface_id = iface.id || '';
                importRecord.if_index = iface.number || '';

                // Recommended unique key
                importRecord.correlation_id =
                    item.device.id + "_" + (iface.number || iface.name);

                // =========================
                // CORE INTERFACE FIELDS
                // =========================

                importRecord.name = iface.name || '';

                // Status
                importRecord.oper_status =
                    iface.Operstatus === true ? 1 : 2;

                importRecord.admin_status =
                    iface.Adminstatus === true ? 1 : 2;

                // Interface characteristics
                importRecord.interface_type = iface.type || '';
                importRecord.speed = iface.speed || 0;
                importRecord.mtu = iface.mtuPkts || 0;

                // =========================
                // OPTIONAL OPERATIONAL DATA
                // =========================

                importRecord.packet_loss = iface.packetloss || 0;

                importRecord.last_change = iface.lastchangesince || '';

                importRecord.last_updated =
				iface.lastupdatedtime || '';

                // Error counters
                importRecord.in_errors = iface.inerr || 0;
                importRecord.out_errors = iface.outerr || 0;

                // Discards
                importRecord.in_discards = iface.indiscard || 0;
                importRecord.out_discards = iface.outdiscard || 0;

                import_set_table.insert(importRecord);

            }
        }

    } catch (ex) {

        import_log.error('Load Data Error: ' + ex);

    }

})(import_set_table, data_source, import_log, last_success_import_time);

